const titleOrder = new Intl.Collator(undefined, { numeric: true, sensitivity: 'base' })

function normalize(value) {
    return String(value ?? '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase()
}

function matchPosition(value, word) {
    let position = value.indexOf(word)
    if (position < 0) return -1
    if (!/[\p{L}\p{N}]/u.test(value.slice(0, position))) return 0
    while (position >= 0) {
        if (!/[\p{L}\p{N}]/u.test(value[position - 1])) return 1
        position = value.indexOf(word, position + 1)
    }
    return 2
}

export function createSearchIndex(tracks) {
    return tracks.map(track => {
        const filename = track.path?.split(/[\\/]/).pop()
        return {
            track,
            fields: [
                [track.title],
                [track.artist, track.album_artist, track.album],
                [track.filename, track.name, filename],
                [track.path]
            ].map(values => [...new Set(values.filter(value => value != null).map(normalize))]),
            order: [track.title || '', track.name || '', track.path || '']
        }
    }).sort((left, right) => {
        for (let index = 0; index < left.order.length; index++) {
            const difference = titleOrder.compare(left.order[index], right.order[index])
            if (difference) return difference
        }
        return 0
    })
}

function trackScore(fields, words) {
    let maxField = 0, fieldTotal = 0, maxPosition = 0, positionTotal = 0
    for (const word of words) {
        let matchedField = -1, matchedPosition = -1
        for (let field = 0; field < fields.length; field++) {
            let position = -1
            for (const value of fields[field]) {
                const match = matchPosition(value, word)
                if (match >= 0 && (position < 0 || match < position)) position = match
                if (position === 0) break
            }
            if (position >= 0) {
                matchedField = field
                matchedPosition = position
                break
            }
        }
        if (matchedField < 0) return null
        maxField = Math.max(maxField, matchedField)
        fieldTotal += matchedField
        maxPosition = Math.max(maxPosition, matchedPosition)
        positionTotal += matchedPosition
    }
    return [maxField, fieldTotal, maxPosition, positionTotal]
}

export function searchTracks(searchIndex, query) {
    const words = normalize(query).trim().split(/\s+/).filter(Boolean)
    if (!words.length) return []
    return searchIndex.map(entry => ({ track: entry.track, score: trackScore(entry.fields, words) }))
        .filter(result => result.score)
        .sort((left, right) => {
            for (let index = 0; index < left.score.length; index++) {
                const difference = left.score[index] - right.score[index]
                if (difference) return difference
            }
            return 0
        })
        .map(result => result.track)
}

const configuredApiUrl = import.meta.env.VITE_API_URL?.replace(/\/+$/, '')
export const API_URL = configuredApiUrl
    ? configuredApiUrl.endsWith('/api') ? configuredApiUrl : `${configuredApiUrl}/api`
    : '/api'

async function request(apiPath, options) {
    let response
    try {
        response = await fetch(API_URL + apiPath, options)
    } catch {
        throw new Error('Cannot reach the music server. Check the connection and try again.')
    }
    let data
    try {
        data = await response.json()
    } catch {
        throw new Error(`The music server returned an unexpected response (${response.status}).`)
    }
    if (!response.ok) {
        throw new Error(data?.error || `The music server could not complete the request (${response.status}).`)
    }
    return data
}

function query(values) {
    const params = new URLSearchParams()
    for (const [key, value] of Object.entries(values)) {
        if (value !== null && value !== undefined) params.set(key, value)
    }
    const query = params.toString()
    return query ? `?${query}` : ''
}

export const fetchFolders = () => request('/folders')
export const fetchAlbums = () => request('/albums')
export const fetchArtists = () => request('/artists')
export const fetchAlbum = (artist, album) => request(`/album${query({ artist, album })}`)
export const fetchArtist = artist => request(`/artist${query({ artist })}`)
export const fetchIndexStatus = () => request('/index')
export const refreshLibrary = () => request('/index', { method: 'POST' })

export function trackUrl(track, cover = false) {
    return `${API_URL}/${cover ? 'track-cover' : 'track'}${query({ path: track.path })}`
}

import express from 'express'

function nullableQuery(value) {
    if (value === undefined) return null
    if (typeof value !== 'string') throw Object.assign(new Error('Invalid query parameter'), { status: 400 })
    return value
}

export function createApiRoutes(library) {
    const router = express.Router()
    router.get('/index', (_req, res) => res.json(library.status))
    router.post('/index', async (_req, res) => res.json(await library.refresh()))
    router.get('/folders', (_req, res) => res.json(library.folders()))
    router.get('/albums', (_req, res) => res.json(library.albums()))
    router.get('/artists', (_req, res) => res.json(library.artists()))
    router.get('/album', (req, res) => res.json(library.album(nullableQuery(req.query.artist), nullableQuery(req.query.album))))
    router.get('/artist', (req, res) => res.json(library.artist(nullableQuery(req.query.artist))))

    router.get('/track', async (req, res, next) => {
        const trackPath = await library.trackFile(req.query)
        res.sendFile(trackPath, { dotfiles: 'allow', cacheControl: false }, error => {
            if (error && !req.aborted) next(error)
        })
    })
    router.get('/track-cover', async (req, res, next) => {
        const cover = await library.cover(await library.trackFile(req.query))
        if (cover.data) res.type(cover.type).send(cover.data)
        else res.sendFile(cover.path, { dotfiles: 'allow', cacheControl: false }, error => {
            if (error && !req.aborted) next(error)
        })
    })
    return router
}

import { describe, expect, it } from 'vitest'
import { isTrack, flattenTracks, playbackOrder, adjacentTrackPath } from '../src/playback.js'

const one = { id: 1, path: 'one.mp3', children: [] }
const two = { id: 2, path: 'two.mp3', children: [] }
const three = { id: 3, path: 'three.mp3', children: [] }
const folder = { path: 'album', children: [one, two] }

describe('playback queue', () => {
    it('uses only files and handles a one-track shuffled queue without retrying random selection', () => {
        expect(isTrack(folder)).toBe(false)
        expect(flattenTracks([folder, three])).toEqual([one, two, three])
        const order = playbackOrder([folder, one], one.path, true, () => 0)
        expect(order).toEqual([one.path])
        expect(adjacentTrackPath(order, one.path, 1, 'none', true)).toBeNull()
        expect(adjacentTrackPath(order, one.path, 1, 'all', true)).toBe(one.path)
    })

    it('shuffles the remaining tracks once and plays each before stopping', () => {
        const order = playbackOrder([one, two, three], two.path, true, () => 0)
        expect(order[0]).toBe(two.path)
        expect(new Set(order)).toEqual(new Set([one.path, two.path, three.path]))
        expect(adjacentTrackPath(order, order[0], 1, 'none')).toBe(order[1])
        expect(adjacentTrackPath(order, order[2], 1, 'none')).toBeNull()
    })

    it('repeats one only after ending and wraps both boundaries only for repeat all', () => {
        const order = playbackOrder([one, two], one.path, false)
        expect(adjacentTrackPath(order, one.path, 1, 'one', true)).toBe(one.path)
        expect(adjacentTrackPath(order, one.path, 1, 'one', false)).toBe(two.path)
        expect(adjacentTrackPath(order, one.path, -1, 'none')).toBeNull()
        expect(adjacentTrackPath(order, one.path, -1, 'all')).toBe(two.path)
        expect(adjacentTrackPath(order, two.path, 1, 'all')).toBe(one.path)
        expect(adjacentTrackPath([], one.path, 1, 'all')).toBeNull()
        expect(adjacentTrackPath(order, 'removed.mp3', 1, 'all')).toBeNull()
    })
})

import test from 'node:test'
import assert from 'node:assert/strict'
import net from 'node:net'
import path from 'node:path'
import { tmpdir } from 'node:os'
import { mkdtemp, mkdir, rm } from 'node:fs/promises'
import { startServer } from '../src/app.js'
import { getConfig } from '../src/config.js'

async function ipv6Available() {
    const server = net.createServer()
    try {
        await new Promise((resolve, reject) => {
            server.once('error', reject)
            server.listen(0, '::1', resolve)
        })
        return true
    } catch (error) {
        if (['EAFNOSUPPORT', 'EADDRNOTAVAIL'].includes(error.code)) return false
        throw error
    } finally {
        if (server.listening) await new Promise(resolve => server.close(resolve))
    }
}

async function fixture(t, host) {
    const root = await mkdtemp(path.join(tmpdir(), 'treble-network-'))
    let runtime
    t.after(async () => {
        try { await runtime?.close() } finally { await rm(root, { recursive: true, force: true }) }
    })
    const musicDirectory = path.join(root, 'music')
    await mkdir(musicDirectory)
    runtime = await startServer({ musicDirectory, databasePath: path.join(root, 'music.db'), port: 0, host })
    const port = runtime.server.address().port
    return { runtime, url: hostname => `http://${hostname}:${port}/api/folders` }
}

async function assertMusicApi(url) {
    const response = await fetch(url, { signal: AbortSignal.timeout(2000) })
    assert.equal(response.status, 200)
    assert.deepEqual(await response.json(), [])
}

test('default and empty HOST preserve the original all-interface binding', async t => {
    assert.equal(getConfig({ MUSIC_DIRECTORY: '.' }).host, undefined)
    assert.equal(getConfig({ MUSIC_DIRECTORY: '.', HOST: '' }).host, undefined)
    const ipv6 = await ipv6Available()
    const { runtime, url } = await fixture(t, getConfig({ MUSIC_DIRECTORY: '.' }).host)
    await assertMusicApi(url('127.0.0.1'))
    if (ipv6) {
        assert.equal(runtime.server.address().address, '::')
        await assertMusicApi(url('[::1]'))
    } else {
        t.diagnostic('IPv6 loopback is unavailable; IPv4 default binding verified.')
    }
})

test('explicit IPv4 hosts remain IPv4 and honor localhost versus all interfaces', async t => {
    const ipv6 = await ipv6Available()
    for (const host of ['127.0.0.1', '0.0.0.0']) {
        assert.equal(getConfig({ MUSIC_DIRECTORY: '.', HOST: host }).host, host)
        const { runtime, url } = await fixture(t, host)
        assert.equal(runtime.server.address().address, host)
        await assertMusicApi(url('127.0.0.1'))
        if (ipv6) await assert.rejects(fetch(url('[::1]'), { signal: AbortSignal.timeout(2000) }))
    }
})

test('an explicit IPv6 localhost host stays local to IPv6', async t => {
    if (!await ipv6Available()) return t.skip('IPv6 loopback is unavailable.')
    const host = '::1'
    assert.equal(getConfig({ MUSIC_DIRECTORY: '.', HOST: host }).host, host)
    const { runtime, url } = await fixture(t, host)
    assert.equal(runtime.server.address().address, host)
    await assertMusicApi(url('[::1]'))
    await assert.rejects(fetch(url('127.0.0.1'), { signal: AbortSignal.timeout(2000) }))
})

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { themes, getTheme, setTheme, initializeTheme } from '../src/themes.js'

beforeEach(() => {
    window.localStorage.clear()
    delete document.documentElement.dataset.theme
})

afterEach(() => {
    vi.restoreAllMocks()
    delete document.documentElement.dataset.theme
})

describe('theme preferences', () => {
    it('offers the original palettes with turquoise as the default', () => {
        expect(themes).toEqual([
            { id: 'turquoise-dreams', label: 'Turquoise Dreams' },
            { id: 'purple', label: 'Purple' },
            { id: 'royalty', label: 'Royalty' },
            { id: 'dark', label: 'Dark' }
        ])
        expect(getTheme()).toBe('turquoise-dreams')
        expect(initializeTheme()).toBe('turquoise-dreams')
        expect(document.documentElement.dataset.theme).toBe('turquoise-dreams')
        expect(window.localStorage.getItem('Treble-Theme')).toBeNull()
    })

    it.each(themes)('applies and saves $label immediately', ({ id }) => {
        expect(setTheme(id)).toBe(id)
        expect(document.documentElement.dataset.theme).toBe(id)
        expect(getTheme()).toBe(id)
        expect(window.localStorage.getItem('Treble-Theme')).toBe(id)
    })

    it('restores the saved theme without rewriting it', () => {
        window.localStorage.setItem('Treble-Theme', 'royalty')
        const write = vi.spyOn(Storage.prototype, 'setItem')
        expect(initializeTheme()).toBe('royalty')
        expect(getTheme()).toBe('royalty')
        expect(write).not.toHaveBeenCalled()
    })

    it.each(['unknown', 'dark-mode', '', 'null'])('uses the default for invalid saved value %j without replacing it', savedTheme => {
        window.localStorage.setItem('Treble-Theme', savedTheme)
        document.documentElement.dataset.theme = 'purple'
        expect(initializeTheme()).toBe('turquoise-dreams')
        expect(document.documentElement.dataset.theme).toBe('turquoise-dreams')
        expect(window.localStorage.getItem('Treble-Theme')).toBe(savedTheme)
    })

    it('ignores unsupported selections and reads an invalid DOM value as the default', () => {
        setTheme('purple')
        expect(setTheme('unknown')).toBe('purple')
        expect(document.documentElement.dataset.theme).toBe('purple')
        expect(window.localStorage.getItem('Treble-Theme')).toBe('purple')
        document.documentElement.dataset.theme = 'unknown'
        expect(getTheme()).toBe('turquoise-dreams')
    })

    it('keeps the default usable when reading storage is blocked', () => {
        vi.spyOn(Storage.prototype, 'getItem').mockImplementation(() => { throw new DOMException('Blocked', 'SecurityError') })
        expect(initializeTheme()).toBe('turquoise-dreams')
        expect(document.documentElement.dataset.theme).toBe('turquoise-dreams')
    })

    it('applies theme changes even when saving storage is blocked', () => {
        vi.spyOn(Storage.prototype, 'setItem').mockImplementation(() => { throw new DOMException('Full', 'QuotaExceededError') })
        expect(setTheme('dark')).toBe('dark')
        expect(document.documentElement.dataset.theme).toBe('dark')
        expect(getTheme()).toBe('dark')
    })

    it('handles browsers that block the storage getter itself', () => {
        vi.spyOn(window, 'localStorage', 'get').mockImplementation(() => { throw new DOMException('Blocked', 'SecurityError') })
        expect(initializeTheme()).toBe('turquoise-dreams')
        expect(setTheme('royalty')).toBe('royalty')
        expect(getTheme()).toBe('royalty')
    })
})

import test from 'node:test'
import assert from 'node:assert/strict'
import { EventEmitter, once } from 'node:events'
import { mkdtemp, mkdir, writeFile, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import path from 'node:path'
import net from 'node:net'
import chokidar from 'chokidar'
import { MusicLibrary } from '../src/library.js'
import { startServer } from '../src/app.js'

const emptyWav = Buffer.from('UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAIA+AAACABAAZGF0YQAAAAA=', 'base64')

async function fixture(t) {
    const root = await mkdtemp(path.join(tmpdir(), 'treble-startup-'))
    const musicDirectory = path.join(root, 'music')
    const databasePath = path.join(root, 'music.db')
    await mkdir(musicDirectory)
    await writeFile(path.join(musicDirectory, 'cached.wav'), emptyWav)
    const cached = new MusicLibrary({ musicDirectory, databasePath })
    cached.database.prepare('INSERT INTO library(id, path, title) VALUES (42, ?, ?)')
        .run(path.join(musicDirectory, 'cached.wav'), 'Cached title')
    await cached.close()
    const errors = []
    let runtime
    t.after(async () => {
        await runtime?.close()
        assert.equal(path.dirname(root), path.resolve(tmpdir()))
        assert.ok(path.basename(root).startsWith('treble-startup-'))
        await rm(root, { recursive: true, force: true })
    })
    return {
        musicDirectory, errors,
        async start(port = 0) {
            runtime = await startServer({ musicDirectory, databasePath, host: '127.0.0.1', port, onError: error => errors.push(error) })
            const base = `http://127.0.0.1:${runtime.server.address().port}/api`
            return { ...runtime, get: route => fetch(base + route), post: () => fetch(base + '/index', { method: 'POST' }) }
        }
    }
}

function watchers(t) {
    const created = []
    let next = Promise.withResolvers()
    t.mock.method(chokidar, 'watch', () => {
        const watcher = new EventEmitter()
        watcher.closeCount = 0
        watcher.close = async () => {
            watcher.closeCount++
            watcher.removeAllListeners()
        }
        created.push(watcher)
        next.resolve(watcher)
        return watcher
    })
    return {
        created,
        async take() {
            const watcher = await next.promise
            next = Promise.withResolvers()
            return watcher
        }
    }
}

test('HTTP serves cached tracks throughout watcher setup and the initial scan, with refresh requests sharing that scan', async t => {
    const controlled = watchers(t)
    const scanEntered = Promise.withResolvers()
    const releaseScan = Promise.withResolvers()
    t.after(() => releaseScan.resolve())
    const scan = MusicLibrary.prototype.scan
    let scanCount = 0
    t.mock.method(MusicLibrary.prototype, 'scan', async function () {
        scanCount++
        scanEntered.resolve()
        await releaseScan.promise
        return scan.call(this)
    })
    const data = await fixture(t)
    const runtime = await data.start()
    const watcher = await controlled.take()
    assert.equal((await (await runtime.get('/index')).json()).syncing, true)
    assert.equal((await (await runtime.get('/folders')).json())[0].title, 'Cached title')
    assert.equal((await runtime.get('/track?id=42')).status, 200)
    assert.equal(scanCount, 0)

    const beforeWatcher = Promise.withResolvers()
    const duringScan = Promise.withResolvers()
    const refresh = runtime.library.refresh.bind(runtime.library)
    let refreshCount = 0
    t.mock.method(runtime.library, 'refresh', () => {
        refreshCount++
        if (refreshCount === 1) beforeWatcher.resolve()
        if (refreshCount === 3) duringScan.resolve()
        return refresh()
    })
    const firstRequest = runtime.post()
    await beforeWatcher.promise
    watcher.emit('ready')
    await scanEntered.promise
    const secondRequest = runtime.post()
    await duringScan.promise
    assert.equal((await (await runtime.get('/index')).json()).syncing, true)
    assert.equal((await (await runtime.get('/folders')).json())[0].title, 'Cached title')
    assert.equal(scanCount, 1)
    releaseScan.resolve()
    await runtime.libraryReady
    for (const request of [firstRequest, secondRequest]) {
        const status = await (await request).json()
        assert.equal(status.syncing, false)
        assert.ok(status.lastSuccess)
    }
    assert.equal(scanCount, 1)
    const track = (await (await runtime.get('/folders')).json())[0]
    assert.equal(track.id, 42)
    assert.equal(track.title, 'cached.wav')
    assert.equal(data.errors.length, 0)
})

test('a watcher startup failure leaves cached HTTP results available and a refresh retries initialization', async t => {
    const controlled = watchers(t)
    const data = await fixture(t)
    const runtime = await data.start()
    const failedWatcher = await controlled.take()
    failedWatcher.emit('error', new Error('Music share is unavailable'))
    await assert.rejects(runtime.libraryReady, /Music share is unavailable/)
    const failedStatus = await (await runtime.get('/index')).json()
    assert.equal(failedStatus.syncing, false)
    assert.equal(failedStatus.error, 'Music share is unavailable')
    assert.equal((await (await runtime.get('/folders')).json())[0].title, 'Cached title')
    assert.equal(failedWatcher.closeCount, 1)

    const retry = runtime.post()
    const watcher = await controlled.take()
    const retryStatus = await (await runtime.get('/index')).json()
    assert.equal(retryStatus.syncing, true)
    assert.equal(retryStatus.error, null)
    watcher.emit('ready')
    assert.equal((await (await retry).json()).error, null)
    assert.equal((await (await runtime.get('/folders')).json())[0].id, 42)
    assert.equal(controlled.created.length, 2)
    assert.equal(data.errors.length, 1)
})

test('a missing music root preserves cached rows and a refresh recovers when the root returns', async t => {
    const controlled = watchers(t)
    const data = await fixture(t)
    await rm(data.musicDirectory, { recursive: true })
    const runtime = await data.start()
    await assert.rejects(runtime.libraryReady, { code: 'ENOENT' })
    assert.equal((await (await runtime.get('/index')).json()).syncing, false)
    assert.equal((await (await runtime.get('/folders')).json())[0].title, 'Cached title')
    assert.equal(controlled.created.length, 0)
    await mkdir(data.musicDirectory)
    await writeFile(path.join(data.musicDirectory, 'cached.wav'), emptyWav)
    const retry = runtime.post()
    const watcher = await controlled.take()
    watcher.emit('ready')
    assert.equal((await (await retry).json()).error, null)
    assert.equal((await (await runtime.get('/folders')).json())[0].id, 42)
})

test('shutdown cancels watcher initialization and an in-flight refresh without leaving the database open', async t => {
    const controlled = watchers(t)
    const data = await fixture(t)
    const runtime = await data.start()
    const watcher = await controlled.take()
    const refreshEntered = Promise.withResolvers()
    const refresh = runtime.library.refresh.bind(runtime.library)
    t.mock.method(runtime.library, 'refresh', () => {
        refreshEntered.resolve()
        return refresh()
    })
    const pendingRequest = runtime.post().then(response => response.json())
    await refreshEntered.promise
    await runtime.close()
    await runtime.libraryReady
    assert.equal((await pendingRequest).syncing, false)
    assert.equal(watcher.closeCount, 1)
    assert.equal(watcher.listenerCount('ready'), 0)
    assert.equal(runtime.library.database.open, false)
    assert.equal(runtime.library.status.lastSuccess, null)
    assert.equal(data.errors.length, 0)
})

test('shutdown waits for the initial scan before closing its database', async t => {
    const controlled = watchers(t)
    const scanEntered = Promise.withResolvers()
    const releaseScan = Promise.withResolvers()
    t.after(() => releaseScan.resolve())
    const scan = MusicLibrary.prototype.scan
    t.mock.method(MusicLibrary.prototype, 'scan', async function () {
        scanEntered.resolve()
        await releaseScan.promise
        return scan.call(this)
    })
    const data = await fixture(t)
    const runtime = await data.start()
    const watcher = await controlled.take()
    watcher.emit('ready')
    await scanEntered.promise
    const refreshEntered = Promise.withResolvers()
    const refresh = runtime.library.refresh.bind(runtime.library)
    t.mock.method(runtime.library, 'refresh', () => {
        refreshEntered.resolve()
        return refresh()
    })
    const pendingRequest = runtime.post().then(response => response.json())
    await refreshEntered.promise
    const closing = runtime.close()
    assert.equal(runtime.library.database.open, true)
    releaseScan.resolve()
    await closing
    await runtime.libraryReady
    assert.equal(runtime.library.database.open, false)
    assert.equal(runtime.library.status.syncing, false)
    assert.equal((await pendingRequest).syncing, false)
    assert.equal(watcher.closeCount, 1)
    assert.equal(data.errors.length, 0)
