export const themes = [
    { id: 'turquoise-dreams', label: 'Turquoise Dreams' },
    { id: 'purple', label: 'Purple' },
    { id: 'royalty', label: 'Royalty' },
    { id: 'dark', label: 'Dark' }
]

const defaultTheme = themes[0].id
const themeIds = new Set(themes.map(theme => theme.id))
const themeStorageKey = 'Treble-Theme'

export function getTheme() {
    const theme = document.documentElement.dataset.theme
    return themeIds.has(theme) ? theme : defaultTheme
}

export function setTheme(id) {
    if (!themeIds.has(id)) return getTheme()
    document.documentElement.dataset.theme = id
    try { window.localStorage.setItem(themeStorageKey, id) } catch { /* The theme still applies when storage is unavailable. */ }
    return id
}

export function initializeTheme() {
    let savedTheme
    try { savedTheme = window.localStorage.getItem(themeStorageKey) } catch { /* Use the default when storage is unavailable. */ }
    const theme = themeIds.has(savedTheme) ? savedTheme : defaultTheme
    document.documentElement.dataset.theme = theme
    return theme
}

import dotenv from 'dotenv'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

export const backendDirectory = fileURLToPath(new URL('../', import.meta.url))
dotenv.config({ path: path.join(backendDirectory, '.env'), quiet: true })

export function getConfig(env = process.env) {
    if (!env.MUSIC_DIRECTORY?.trim()) throw new Error('MUSIC_DIRECTORY is required')
    const port = Number(env.PORT ?? 4001)
    if (!Number.isInteger(port) || port < 0 || port > 65535) throw new Error('PORT must be between 0 and 65535')
    return {
        host: env.HOST || undefined,
        port,
        musicDirectory: path.resolve(backendDirectory, env.MUSIC_DIRECTORY),
        databasePath: path.resolve(backendDirectory, env.MUSIC_DB_PATH || 'music.db'),
        corsOrigins: env.CORS_ORIGINS?.split(',').map(origin => origin.trim()).filter(Boolean)
    }
}

export function formatSecondsAsTime(seconds) {
    const total = Number.isFinite(seconds) && seconds > 0 ? Math.floor(seconds) : 0
    const hours = Math.floor(total / 3600)
    const minutes = Math.floor((total % 3600) / 60)
    const remainder = total % 60
    const time = `${String(minutes).padStart(2, '0')}:${String(remainder).padStart(2, '0')}`
    return hours ? `${hours}:${time}` : time
}

export function savedVolume(value) {
    if (value === null || value.trim() === '') return 1
    const volume = Number(value)
    return Number.isFinite(volume) && volume >= 0 && volume <= 1 ? volume : 1
}
